sys_script_include.script:
var MedicationUtils = Class.create();
MedicationUtils.prototype = {
    initialize: function() {
    },

    getTotalDosage: function(id){
        var medic = new GlideRecord('u_medication')
        medic.addQuery('number', id)
        medic.query()
        if(medic.next()){
            if (medic.u_dosage && medic.u_frequency){
                var freq = null;
                if (medic.u_frequency == 'once_daily'){
                    freq = 1;
                }
                if (medic.u_frequency == 'twice_daily'){
                    freq = 2;
                }
                if (medic.u_frequency == 'thrice_daily'){
                    freq = 3;
                }
                if(medic.u_frequency == 'once_week'){
                    freq = 1/7;
                }
                var days = gs.dateDiff(medic.u_start_date,medic.u_end_date,true);
                var dosage = medic.u_dosage;
                var ans = freq * dosage * (days/(3600*24));
                return ans;
            }
        }
    },

    isMedicationAvailable: function(id) {
        var medic = new GlideRecord('u_medication');
        if (medic.get(id)) {
            return medic.active == true; 
        }
        return false;
    },

    getMedicationByID: function(id) {
        var medic = new GlideRecord('u_medication');
        if (medic.get(id)) {
            return medic;
        }
        return null;
    },

    getMedicationsByPatientID: function(id) {
        var meds = new GlideRecord('u_medication');
        meds.addQuery('u_patient_id', id);
        meds.query();
        return meds; 
    },

    type: 'MedicationUtils'
};
